    ["620e128"] = "pero tu especialización no golpea con esa arma y no lo usa.",
    ["f8fc3c4"] = "que para tu especialización cuenta.",
    ["704cc42"] = "Armadura:",
    ["4842b23"] = "Las demás diferencias (armadura, daño...) no cuentan para tu especialización.",
    ["46e81de"] = "Las estadísticas que cuentan para ti son iguales.",
    ["984170a"] = "Para tu especialización en esta ranura lo que más cuenta es: %s.",
    ["a6ac637"] = "Con las mismas estadísticas, más armadura es mejor.",
    ["d39c34f"] = "Con las mismas estadísticas, menos armadura es peor.",
    ["8878fa5"] = "La rotación de Beast Mastery de la guía (subida 1-60): sin cuerpo a cuerpo; Hunter's Mark y Serpent Sting como apertura, halcones (Summon Hawk) desde el 25, Aimed Shot y Arcane Shot, Multi-Shot y Explosive Trap contra varios monstruos. Las habilidades con reutilización larga (Bestial Wrath, Rapid Fire, raciales) quedan fuera de la rotación, para usarlas a mano. Creada por BuildBeast.",
    ["3fcb6ff"] = "Rotación de BuildBeast para subir de nivel del 1 al 60, tomada de la guía: Hekili solo elige entre ellas las habilidades que ya has aprendido. Creada por BuildBeast.",
    ["f7219d4"] = "para esta especialización BuildBeast todavía no tiene rotación propia: Hekili usa la suya.",
    ["f23ecca"] = "Hekili no está cargado.",
    ["2ec553f"] = "No he podido crear la prioridad en Hekili.",
    ["9e1f59d"] = "Hekili ya usa la prioridad: %s",
    ["bbf6862"] = "prioridad de Hekili establecida: %s",
    ["3f1c97f"] = "Hekili no ha aceptado la prioridad.",
    ["511ff29"] = "brillo de los botones:",
    ["c172ef4"] = "activado",
    ["72960be"] = "desactivado",
    ["969f47a"] = "Oro = usar ahora, azul = la siguiente.",
    ["2850cfb"] = "sombreado de reutilización:",
    ["c4ad91d"] = "visible",
    ["aba8815"] = "oculto",
    ["babe955"] = "números de reutilización en los botones:",
    ["48983fc"] = "activados",
    ["3424735"] = "desactivados",
    ["8b823dc"] = "Zygor no está listo.",
    ["7496082"] = "marcas de talentos de Zygor:",
    ["1b9f260"] = "Vuelve a abrir la ventana de talentos.",
    ["7c4161e"] = "Cambias de objetivo sin detener Auto Shot.",
    ["3ddfa3b"] = "La mascota ataca al objetivo que marcas con Hunter's Mark.",
    ["d00e00c"] = "Un solo botón para las habilidades cuerpo a cuerpo, para cuando te atacan.",
    ["458bcf6"] = "Alterna Mongoose Bite y Counterattack con un solo botón, tras una esquiva o una parada.",
    ["7e3322d"] = "Lanza la habilidad e inicia el ataque automático, incluso antes de entablar combate. En lugar de Heroic Strike puedes poner otra habilidad. Hace falta suficiente ira.",
    ["4215a24"] = "Sunder Armor sobre el enemigo bajo el cursor, sin seleccionarlo.",
    ["fade647"] = "Blessing of Protection sobre el aliado bajo el cursor (si no hay, sobre tu objetivo).",
    ["0ea3265"] = "Blessing of Freedom sobre el aliado bajo el cursor.",
    ["474ed6a"] = "Cleanse sobre el aliado bajo el cursor.",
    ["dd398c9"] = "Invoca el Advanced Target Dummy en el cursor y le lanza Blessing of Protection: púlsala dos veces, sin enfriamiento global activo.",
    ["ad171ca"] = "Divine Shield sobre ti; al pulsar otra vez lo quitas al instante. Púlsala dos veces, sin enfriamiento global activo.",
    ["8b1f0a2"] = "Inicia el ataque automático y lanza Holy Strike. No la pongas sobre Holy Shield.",
    ["39da0a5"] = "Power Word: Shield sobre el cursor, si no sobre ti.",
    ["885b4fd"] = "Greater Heal sobre el cursor, si no sobre el objetivo, si no sobre ti.",
    ["f6044e4"] = "Detiene el lanzamiento en curso y vuelve a lanzar Greater Heal: para cuando otro sanador ya ha curado a ese objetivo.",
    ["73afb8f"] = "Inner Focus y enseguida Prayer of Healing: para emergencias.",
    ["91996ef"] = "Dispel Magic inteligente: quita magias dañinas a los aliados y beneficiosas a los enemigos.",
    ["b32d1df"] = "Prayer of Mending sobre el cursor, si no sobre el objetivo, si no sobre ti.",
    ["4e5454e"] = "Detiene el lanzamiento y usa Shadow Word: Death sobre un monstruo casi muerto que huye o sobre un tótem.",
    ["4b2ea52"] = "Aplica Deadly Poison al arma de la mano principal; el icono muestra la duración.",
    ["73d1f2d"] = "Aplica Instant Poison al arma de la mano secundaria; el icono muestra la duración.",
    ["672d6cc"] = "Pick Pocket como apertura, luego Garrote (puedes cambiarlo por Cheap Shot o Ambush).",
    ["c2da64b"] = "Manda a atacar a la mascota y al personaje con un solo botón: así no te quedas parado mientras subes.",
    ["8833bc9"] = "Como BB Attacco, pero además lanza Stormstrike (en lugar de la macro anterior).",
    ["79e760c"] = "Totemic Projection donde está el cursor.",
    ["93ec012"] = "Nature's Swiftness y enseguida Healing Wave sobre el cursor: curación de emergencia instantánea. Quita [@mouseover] si no quieres la curación con el cursor.",
    ["ddfe74e"] = "Polymorph sobre el objetivo en foco; si no hay o no es enemigo, sobre el objetivo actual.",
    ["425c144"] = "Usa los dos abalorios con un solo botón (ranuras 13 y 14).",
    ["23fc3c4"] = "Combustion junto con los dos abalorios.",
    ["6d5d784"] = "Manda a la mascota a atacar y luego la pone en pasivo, como en la guía.",
    ["3b9d855"] = "Amplify Curse y Bane of Agony juntos: para la apertura o cuando Amplify Curse está lista.",
    ["67eb4db"] = "Drain Life que puedes pulsar varias veces sin interrumpirlo.",
    ["c24583f"] = "Corruption sobre el objetivo bajo el cursor: para poner DOTs en varios enemigos. Cambia Corruption por otro DOT.",
    ["de046d0"] = "Fel Domination y enseguida Imp: para volver a llamar a la mascota tras morir, o para la build de ejecución.",
    ["0da2d35"] = "Fel Domination y enseguida Succubus: para volver a llamar a la mascota tras morir.",
    ["701f8c9"] = "Bane of Havoc sobre el objetivo bajo el cursor.",
    ["6177927"] = "Immolate sobre el foco (el objetivo de Bane of Havoc).",
    ["687eb32"] = "Corruption sobre el foco.",
    ["dfc9982"] = "Bane of Doom sobre el foco.",
    ["f14c9c9"] = "Bane of Agony sobre el foco.",
    ["37f2591"] = "Hurricane que no se interrumpe solo si pulsas el botón durante el lanzamiento.",
    ["e041704"] = "Moonfire sobre el cursor: para poner DOTs en varios enemigos (cambia a Insect Swarm para el otro).",
    ["11b387e"] = "Feral Charge (gato) y luego Prowl, si no estás ya en sigilo.",
    ["9bca5ec"] = "Cambia de forma para librarte de raíces y ralentizaciones: de oso a gato, de gato a gato.",
    ["38e0846"] = "Un solo botón: Aquatic Form en el agua, Travel Form al aire libre, si no Cat Form.",
    ["53406a7"] = "Entra en Dire Bear Form una sola vez, sin salir si pulsas de nuevo.",
    ["b18da61"] = "Growl sobre el foco, luego sobre el cursor, luego sobre el objetivo.",
    ["beb6029"] = "Nature's Swiftness y enseguida Healing Touch: curación de emergencia instantánea (sale de la forma y detiene el lanzamiento).",
    ["8c5c182"] = "No se pueden crear macros en combate: inténtalo después.",
    ["e3c93a8"] = "Macros: %d creadas, %d actualizadas%s. Ábrelas con /macro y arrástralas a las barras.",
    ["99effc3"] = "%d no creadas (ya tienes 18 macros del personaje)",
    ["530c645"] = "No hay macros para esta especialización.",
    ["1e74c8f"] = "BuildBeast creará %s macros para tu personaje:\n%s\n\nSi ya existen las actualiza. Luego las arrastras a las barras.",
    ["d8354a3"] = "Crear",
    ["160009a"] = "Cancelar",
    ["054716f"] = "Guerrero",
    ["3e76e85"] = "Paladín",
    ["69c8129"] = "Cazador",
    ["dd6c053"] = "Pícaro",
    ["3a3f441"] = "Sacerdote",
    ["fabeb14"] = "Chamán",
    ["a5a0a92"] = "Mago",
    ["8b0635d"] = "Brujo",
    ["3d8e8ed"] = "Druida",
    ["ce774d9"] = "SÍ",
    ["c2f3f48"] = "NO",
    ["672c529"] = "PARECIDO",
    ["656ff24"] = "Bear Form, Growl, Maul (misión de clase), Nature's Grasp, Demoralizing Roar",
    ["50d1ea3"] = "Bash; misión para Cure Poison",
    ["2290f2a"] = "Swipe; misión para Aquatic Form",
    ["227f378"] = "Faerie Fire (ahora también en las formas), Hibernate",
    ["469f184"] = "Cat Form (misión), Prowl, Claw, Rip, Shred, Starfire, Rebirth, Omen of Clarity",
    ["eda7053"] = "Mark of the Wild sobre ti. Abre con Wrath y sigue lanzándolo. Cuando el maná es bajo remata al monstruo con el arma, así el maná vuelve. Cúrate con Healing Touch entre combates.",
    ["3d495a9"] = "Mantén Mark of the Wild y Thorns sobre ti y pon Rejuvenation antes de entablar combate. Abre con Wrath, añade Moonfire y sigue con Wrath. En una zona concurrida abre con Moonfire, que es instantáneo.",
    ["bb21cc8"] = "La misión de clase te da Bear Form, Growl y Maul. Nature's Grasp inmoviliza al próximo monstruo que te golpee; Demoralizing Roar es para la forma de oso.",
    ["a9ba21f"] = "Enrage te da ira al instante y más en 10 segundos, pero baja tu armadura.",
    ["9c7f3ca"] = "Feral es la especialización de gato y oso, y la que sube con más fluidez: Prowl y Dash te llevan de un objetivo a otro y casi nunca te detienes por el maná. En Bear Form: Mark of the Wild y Thorns sobre ti, y deja que la ira de tus golpes pague Maul, que añade daño al golpe siguiente. Contra varios monstruos Demoralizing Roar para debilitarlos.",
    ["ce230c2"] = "En Bear Form: Enrage antes del pull (la pérdida de armadura pesa menos), Faerie Fire baja la armadura del monstruo, Swipe es el relleno y Maul gasta la ira que sobra. Con varios monstruos primero Demoralizing Roar, luego Swipe.",
    ["78a0920"] = "Cat Form: primero Mark of the Wild y Thorns. Abre desde Prowl con Shred (Prowl te lleva detrás del monstruo), luego Faerie Fire, luego Claw para acumular puntos de combo o Shred cuando estés detrás. Con cuatro o más puntos de combo Rip si el monstruo vive lo bastante. Bear Form sigue siendo mejor contra varios monstruos: la forma de gato no tiene nada que golpee a más de uno.",
    ["540175c"] = "Rake: abre desde Prowl con Shred, Faerie Fire, luego Rake y mantén su sangrado siempre activo en un monstruo que viva lo bastante; luego Claw o Shred desde atrás. Con 4 o más puntos: Rip si el monstruo vive, Ferocious Bite para rematar.",
    ["87e3251"] = "Lacerate (oso): un sangrado que se acumula hasta 5 veces; contra un solo monstruo es tu relleno, y Maul gasta la ira que sobra. Con varios monstruos Demoralizing Roar y luego Swipe. Blood Frenzy: en oso cada crítico da 5 de ira, en gato un crítico con una habilidad de puntos de combo da uno más.",
    ["25dc320"] = "Predatory Discipline: Ferocious Bite sigue ganando daño con la energía extra, pero no la gasta.",
    ["042c952"] = "Ravage: abre desde Prowl con Ravage (debes estar detrás del monstruo), luego Faerie Fire, Rake con el sangrado siempre activo, luego Claw o Shred desde atrás; con 4 o más puntos Rip o Ferocious Bite para rematar. Poised quita 10 de energía a tu primer golpe si empiezas con la energía llena.",
    ["4560b4d"] = "Dire Bear Form: Enrage antes del pull, Faerie Fire, Primal Bite en cada reutilización (un mordisco fuerte con 6 segundos de reutilización y mucha amenaza), Lacerate en medio contra un solo monstruo y Maul para gastar el resto; con varios monstruos Demoralizing Roar y Swipe en lugar de Lacerate.",
    ["ff10d54"] = "Gato: Shifting Power cuando tienes menos de 50 de energía (convierte maná en 40 de energía, 8 segundos de reutilización).",
    ["0d8ecd7"] = "Feral quiere ante todo el daño por segundo del arma, porque tu forma se basa en él, y la velocidad del arma no cuenta. Luego Golpe (Hit), crítico, Agilidad y Fuerza.",
    ["4a841e3"] = "Guardian es el oso: usa el mismo plan de talentos que Feral. Bear Form con Mark of the Wild y Thorns sobre ti; la ira de tus golpes paga Maul. Contra varios monstruos Demoralizing Roar.",
    ["7b551a8"] = "Enrage antes del pull, Faerie Fire sobre el monstruo, Swipe como relleno y Maul con la ira que sobra. Con varios monstruos Demoralizing Roar y luego Swipe.",
    ["af4c8fb"] = "Lacerate es tu relleno contra un solo monstruo (se acumula hasta 5 veces); Maul gasta la ira que sobra. Con varios monstruos Demoralizing Roar y Swipe.",
    ["5213241"] = "Dire Bear Form: Enrage antes del pull, Faerie Fire, Primal Bite en cada reutilización (6 segundos, mucha amenaza), Lacerate en medio contra un solo monstruo y Maul para el resto; con varios monstruos Demoralizing Roar y Swipe en lugar de Lacerate.",
    ["fc61247"] = "El oso quiere el daño por segundo del arma (la velocidad no cuenta), luego Golpe (Hit), crítico, Agilidad y Fuerza. Para la forma de oso también valen Fuerza y poder con hechizos, y el Aguante cuenta más si haces de tanque.",
    ["25acd2a"] = "Balance y Restoration empiezan igual: Improved Wrath (medio segundo menos de lanzamiento y la mitad del maná) y Nature's Focus. Balance empieza lento, pero acelera cuando Insect Swarm se une a Moonfire en cada monstruo.",
    ["9c1fb9f"] = "Mark of the Wild y Thorns sobre ti, Rejuvenation antes de entablar combate. Abre con Wrath o con Moonfire si la zona está concurrida. Moonfire e Insect Swarm sobre el monstruo (un DOT que además reduce su probabilidad de golpear), luego Wrath. Regrowth si necesitas curación, Nature's Grasp antes de que llegue un segundo monstruo.",
    ["7f51b3b"] = "Moonfire e Insect Swarm sobre cada monstruo que combates, luego Wrath. Con tres o más monstruos, Hurricane.",
    ["c845919"] = "Con tres o más monstruos, Barkskin y luego Hurricane.",
    ["d66aa4c"] = "Eclipse: cada Wrath quita medio segundo a tus dos Starfire siguientes, así Starfire entra por fin en la rotación: un Wrath seguido de dos Starfire.",
    ["7e94c11"] = "Moonkin Form: mucha armadura, 3% de crítico para el grupo y Omen of Clarity se activa el doble de a menudo; no puedes lanzar curaciones mientras estás en ella, así que sal para Regrowth y vuelve a entrar. Rotación: Moonfire e Insect Swarm, luego un Wrath y dos Starfire.",
    ["ef6797a"] = "Para Balance y Restoration primero el poder con hechizos, luego Intelecto, crítico y Espíritu; Restoration añade el poder de curación a partir del 60. Un bastón de lanzador puede venir de una misión de facción.",
    ["a91a8ac"] = "Restoration es la que sube más despacio, porque curar no mata monstruos: puedes subir como Balance o Feral y curar igualmente en las mazmorras.",
    ["7a2110b"] = "Mark of the Wild y Thorns sobre ti, Rejuvenation antes de entablar combate. Abre con Wrath o Moonfire en una zona concurrida, luego Moonfire e Insect Swarm sobre el monstruo y Wrath. Regrowth si necesitas curación, Nature's Grasp antes de que llegue un segundo monstruo.",
    ["937f66e"] = "Swiftmend: curación instantánea sobre quien tiene tu Rejuvenation o Regrowth. Cuando recibes daño, Swiftmend sobre tu Rejuvenation y luego Regrowth si hace falta más. Con tres o más monstruos, Hurricane.",
    ["2061d06"] = "Nature's Swiftness: tu próximo hechizo de naturaleza es instantáneo. Déjalo fuera de la rotación, para el momento en que necesites una curación grande ya.",
    ["1164b95"] = "Wild Growth: cura al objetivo y a su grupo durante 7 segundos, más fuerte al principio: en grupo cuando hay más de uno herido.",
    ["8f8a34a"] = "Aspect of the Hawk, domar a la mascota (misión de clase: Tame Beast, Call Pet, Feed Pet, Revive Pet)",
    ["2b3db50"] = "Auto Shot empieza solo: quédate quieto medio segundo antes de cada disparo y deja que llegue el monstruo. Raptor Strike si te alcanza. A menos de 8 metros los disparos a distancia no funcionan.",
    ["9329f10"] = "Añade Serpent Sting como apertura, solo sobre monstruos que duran: si muere en pocos segundos el daño se desperdicia.",
    ["d2b7bf1"] = "Hunter's Mark antes del pull, luego Serpent Sting. Arcane Shot cuando tengas maná.",
    ["85f72cd"] = "El centro es Auto Shot, con Arcane Shot cuando tengas maná. Antes del pull Hunter's Mark, luego Serpent Sting como apertura. Mientras el monstruo corre hacia ti Concussive Shot lo ralentiza; Raptor Strike si te alcanza.",
    ["71067ff"] = "Tienes la mascota: mándala por delante unos segundos, luego Serpent Sting. Mantén siempre Aspect of the Hawk y dale de comer a la mascota. Concussive Shot si el monstruo se vuelve hacia ti, Raptor Strike como último recurso.",
    ["bb6f64b"] = "Rapid Fire (+40% de velocidad de ataque durante 15 segundos) queda fuera de la rotación: guárdalo para el pull que lo necesite.",
    ["ebe54cf"] = "El centro es Aimed Shot cada vez que está listo (2 segundos de lanzamiento, 6 segundos de reutilización compartidos con Multi-Shot), con Auto Shot en los huecos. Antes del pull Hunter's Mark, mascota por delante, luego Serpent Sting. Arcane Shot cuando tengas maná. Si el monstruo te alcanza: Disengage. Con varios monstruos: Multi-Shot en lugar de Aimed Shot.",
    ["c943332"] = "El centro son los halcones (Summon Hawk): cada halcón dura 18 segundos y puede haber dos fuera; invoca uno nuevo cuando caduque uno de los dos. Luego Aimed Shot cuando esté listo y Auto Shot en los huecos. Arcane Shot usa la misma reutilización que los halcones, así que espera después de ellos. El resto como antes.",
    ["ab9f050"] = "Añade Intimidation: si el monstruo se vuelve contra ti aturde y da amenaza a la mascota; Disengage cuando no esté lista. Con varios monstruos: primero Explosive Trap, luego Multi-Shot en la reutilización de Aimed Shot.",
    ["bf06335"] = "Bestial Wrath (2 minutos) y Volley quedan fuera de la rotación: úsalos a mano en pulls peligrosos o con grupos grandes. Desde el 42 casi todos los puntos van a Marksmanship: la rotación no cambia.",
    ["e096af7"] = "Beast Mastery dispara desde lejos: cuentan el DPS del arma a distancia y luego la Agilidad. El arma cuerpo a cuerpo solo sirve por sus estadísticas.",
    ["b35c3c9"] = "El centro es Aimed Shot cada vez que está listo, con Auto Shot en los huecos. Tras la ventaja de la mascota el primer disparo debe ser el más fuerte: con Rapid Killing a la espera es Aimed Shot. Antes del pull Hunter's Mark y mascota por delante; Serpent Sting sobre cada monstruo, porque si muere con Serpent Sting encima tu próximo disparo en 20 segundos hace hasta un 20% más. Arcane Shot cuando tengas maná. Si el monstruo te alcanza: Disengage. Con varios monstruos: Multi-Shot en lugar de Aimed Shot.",
    ["cf4e14e"] = "Antes del pull también Trueshot Aura, además de Hunter's Mark.",
    ["51e16cf"] = "Sniper Shot es tu disparo más fuerte: 4 segundos de lanzamiento, 15 segundos de reutilización, hasta 45 metros, y durante 10 segundos tus tres disparos siguientes llegan 10 metros más lejos. Úsalo como primer disparo tras la ventaja de la mascota cuando tengas tiempo para el lanzamiento, mejor con Rapid Killing a la espera; si no, Aimed Shot. Con varios monstruos: primero Explosive Trap, luego Multi-Shot en la reutilización de Aimed Shot.",
    ["c8aaa16"] = "El centro son los halcones (Summon Hawk): uno nuevo cada vez que caduca uno de los dos. Luego Aimed Shot cuando esté listo y Auto Shot en los huecos; Sniper Shot como primer disparo si tienes tiempo. Arcane Shot espera después de los halcones.",
    ["1fe9ee6"] = "Marksmanship dispara desde lejos: cuentan el DPS del arma a distancia (a igualdad, mejor una más lenta con golpes grandes, porque Aimed Shot se basa en un golpe del arma) y la Agilidad. Con Careful Aim el Intelecto también cuenta como poder de ataque, además del maná. El arma cuerpo a cuerpo solo sirve por sus estadísticas.",
    ["184fc61"] = "Survival combate en dos lugares. A distancia: Multi-Shot cada vez que está listo (es instantáneo y comparte reutilización con Aimed Shot, así que casi no usas Aimed Shot), más Serpent Sting, Arcane Shot y Auto Shot. Cuerpo a cuerpo: Immolation Trap, luego Raptor Strike (instantáneo, 6 segundos de reutilización) y Mongoose Bite tras una esquiva. Hunter's Mark antes del pull y la mascota entra primero.",
    ["d85837a"] = "Strider Kick: una patada con todo el daño del arma que te hace un 30% más rápido durante 3 segundos: es el botón que cierra el cuerpo a cuerpo y te devuelve a distancia. Cuerpo a cuerpo primero Immolation Trap, Mongoose Bite cuando se pueda, Raptor Strike. A distancia Multi-Shot cuando esté listo, Serpent Sting, Arcane Shot, Auto Shot. Con varios monstruos Explosive Trap ocupa el lugar de Immolation Trap, porque una sola reutilización vale para todas las trampas.",
    ["e7233e1"] = "Con Lacerating Strikes cada Mongoose Bite deja un sangrado igual al 40% del daño del golpe, en 21 segundos.",
    ["10bfe36"] = "Survival dispara pero también golpea con el arma cuerpo a cuerpo (Raptor Strike y Strider Kick se basan en su daño): ayuda una de dos manos lenta. Luego cuenta la Agilidad. Desde el 49 Careful Aim hace que el Intelecto sirva también como poder de ataque.",
    ["0718298"] = "Blink, Evocation, Mana Shield, Blizzard, Fire Ward, teletransporte a dos capitales (y Arcane Blast para Arcane y Fire)",
    ["ad986c1"] = "Conjure Mana Agate (la primera gema de maná)",
    ["3e67dd9"] = "Ice Armor; misión de clase (la varita Ice Fury)",
    ["3ddbf7c"] = "Frostfire Bolt, primeros portales",
    ["3d9e7fb"] = "Mantén siempre Arcane Intellect y un hechizo de armadura (por ahora Frost Armor). La regeneración de maná se detiene 5 segundos tras cada hechizo que cuesta maná: un monstruo casi muerto no vale un lanzamiento completo. Hacia el nivel 5 consigue una varita (un Encantador te hace la Lesser Magic Wand, la Greater Magic Wand desde el 13): hasta los talentos puede hacer tanto daño como tus hechizos o más y no gasta maná.",
    ["2991425"] = "Abre con Frostbolt a la distancia máxima, así el monstruo llega ralentizado. Sigue lanzando mientras se acerca, luego Fire Blast para rematar y la varita para lo que quede.",
    ["5d6b9a7"] = "Frost Nova congela todo a tu alrededor: el daño la rompe, así que puedes retroceder y seguir lanzando. Si el monstruo llega al cuerpo a cuerpo: Frost Nova y retrocede.",
    ["11f2d67"] = "Con Missile Barrage: abre desde lejos con Frostbolt (Arcane y Frost) o Fireball (Fire), sigue lanzando y cuando salte el proc lanza Arcane Missiles: se convierten en una andanada gratis. Missile Barrage es el talento que más maná te ahorra mientras subes.",
    ["b985201"] = "Evocation es una canalización de 8 segundos que te devuelve gran parte del maná. Blink en cuanto se recarga mientras corres te hace llegar aproximadamente un quinto antes. La piedra de hogar es mejor usarla para la zona de misiones, porque el teletransporte ya te lleva a una capital.",
    ["a601e53"] = "Arcane Blast: cada lanzamiento te da daño con hechizos igual al 12% de tu Intelecto, hasta 4 cargas que duran 18 segundos; cada carga hace que el próximo lanzamiento cueste un 100% más. Frostbolt desde lejos, luego Arcane Blast de una a tres veces hasta que salte Missile Barrage, luego Arcane Missiles. Deja que las cargas caduquen en lugar de llegar a cuatro. Gasta Clear Casting en un Arcane Blast cargado. Cuerpo a cuerpo: Frost Nova y retrocede. Fire Blast para rematar y la varita.",
    ["e55eb73"] = "Arcane Wrath: un golpe pesado con 6 segundos de reutilización (el daño extra vale el 5% de tu maná máximo). Frostbolt desde lejos, luego Arcane Wrath, Arcane Blast de una a tres veces hasta Missile Barrage y Arcane Missiles; Frost Nova cuando se acerque, otra vez Arcane Wrath, luego Fire Blast y la varita para matar. Deja que las cargas caduquen o el coste creciente te vacía; Clear Casting solo en un Arcane Blast cargado o un Arcane Wrath, nunca en un hechizo barato.",
    ["65a5bf0"] = "Presence of Mind: tu próximo hechizo con lanzamiento de menos de 10 segundos es instantáneo.",
    ["c51b464"] = "Arcane Power: +30% de daño durante 15 segundos, a costa de +30% de maná.",
    ["dfc4101"] = "Abre con Pyroblast o Frostbolt desde lejos, luego Arcane Wrath. Arcane Blast de una a tres veces hasta Missile Barrage, luego los misiles. Desde el 58 Fire Blast en cuanto se recargue y Pyroblast cuando Heating Up llegue a 3 cargas.",
    ["9226a40"] = "Para cada especialización el poder con hechizos va primero, porque tus hechizos crecen mucho con él. El Intelecto aumenta el maná y un poco el crítico; el Espíritu reduce las pausas para beber, y para Arcane cuenta mucho porque gasta maná rápido.",
    ["ebbbb02"] = "Fireball desde lejos. Uno o dos Arcane Blast hasta que salte Missile Barrage, luego los misiles. Fire Blast en cuanto se recargue. Un monstruo con poca vida no hace falta mantenerlo a distancia: deja que te golpee unas veces, por debajo del 15% lo remata la varita.",
    ["9e5f918"] = "Scorch rellena los huecos incluso con el monstruo encima.",
    ["ab79a6b"] = "Abre con Frostfire Bolt desde lejos, luego uno o dos Arcane Blast hasta que salte Missile Barrage y los misiles. Fire Blast en cuanto se recargue, Scorch para rellenar los huecos, la varita para el último 15%.",
    ["bece8ec"] = "Pyroblast y Heating Up: cada crítico no periódico de Fireball, Frostfire Bolt, Fire Blast o Scorch hace tu próximo Pyroblast un cuarto más rápido, hasta 3 cargas, y Fire Blast añade una carga con cada daño. Lanza Pyroblast cuando Heating Up llegue a 3 cargas.",
    ["196edb9"] = "Para cada especialización el poder con hechizos va primero. El Intelecto aumenta el maná y un poco el crítico; el Espíritu reduce las pausas para beber.",
    ["38bc29a"] = "Frost empieza con Precision: dos puntos llevan la probabilidad de golpear a monstruos de tu nivel al 100%.",
    ["c690916"] = "Frostbite: tus efectos de hielo tienen un 15% de probabilidad de congelar al objetivo durante 5 segundos. Ice Lance (desde el 27): contra un objetivo congelado hace un 300% más, con 8 segundos de reutilización compartidos con Fire Blast.",
    ["1f1ed9a"] = "Frostbolt desde lejos, y sigue lanzando mientras llega el monstruo. Cuando Frostbite congela al objetivo: un Frostbolt con Ice Lance justo detrás; si Ice Lance no está lista, Cone of Cold. Cuerpo a cuerpo: Frost Nova y retrocede, luego Frostbolt e Ice Lance sobre el monstruo congelado. Missile Barrage: lanza los misiles, o guárdalo para el próximo monstruo si este está casi muerto. Fire Blast o la varita para un monstruo bajo de vida que no esté congelado.",
    ["2e43c7c"] = "Con Fingers of Frost tus próximos dos hechizos tratan al objetivo como congelado: el primero sobre un Frostbolt, el segundo sobre un Frostbolt con Ice Lance (o con Cone of Cold si Ice Lance aún no está lista). Su punto fuerte está en los 30: tras Shatter un objetivo congelado recibe tus golpes más duros.",
    ["cecd125"] = "Ice Barrier primero, y vuelve a lanzarlo cuando pase el minuto: además del escudo da un 15% más de daño de hielo durante un minuto.",
    ["959453a"] = "Winter's Chill: Frostbolt e Ice Lance la acumulan sobre el objetivo hasta 5 veces, y el próximo Cone of Cold hace un 20% más por cada carga.",
    ["5a9d3eb"] = "Redemption (misión de clase)",
    ["3d343ad"] = "Seal of Command (talento de Retribution), Seal of Justice",
    ["32b558d"] = "Doble especialización y montura",
    ["38d0905"] = "Antes del pull Blessing of Might y Devotion Aura. Luego tres pasos: Seal of Righteousness, Judgment mientras corres hacia el monstruo, Holy Strike. Después, Judgment y Holy Strike cada vez que estén listos, y renueva el sello solo cuando esté por acabar (Judgment ya no lo consume y no usa el enfriamiento global). El maná es también tu curación: si el próximo golpe mata al monstruo, sáltate el botón. Si terminas un combate con maná de sobra conviértelo en vida con Holy Light. En peligro: primero Divine Protection sobre ti, luego curación.",
    ["f580de7"] = "Consecration cuando combates a varios enemigos o te sobra maná: cuesta más que Judgment y Holy Strike juntos y necesita 8 segundos para hacer todo su daño. Exorcism sobre cada no-muerto o demonio, incluso desde 30 metros.",
    ["2ea2c89"] = "Añade Hammer of Wrath: remata a los enemigos por debajo del 20% de vida.",
    ["c8d4778"] = "Retribution y Protection empiezan en el mismo árbol con casi los mismos talentos. En lugar de Deflection (5% de parada) puedes elegir Benediction: todas las habilidades instantáneas cuestan un 10% menos de maná, y Consecration resulta más fácil de pagar.",
    ["a81d5b1"] = "Con Seal of Command: Blessing of Kings o Might y Retribution Aura. Sobre un monstruo que dura: primero Judgment de Seal of the Crusader (el monstruo recibe más daño sagrado), luego pasa a Seal of Command si tienes un arma lenta; con un arma rápida o mucho daño con hechizos es mejor Seal of Righteousness. Luego Judgment y Holy Strike en cada reutilización. Truco: el Judgment de Seal of Command hace casi el doble contra un objetivo aturdido, así que abre con Hammer of Justice y luego Judgment.",
    ["733e5e6"] = "Sacred Arbiter: Holy Strike golpea un 20% más fuerte y renueva todos los Judgment sobre el objetivo, también los de otros paladines.",
    ["a01f90a"] = "Champion of the Light convierte hasta el 60% de tu Intelecto en daño con hechizos: el equipo con poder con hechizos resulta aún mejor. En el 40 Unsealed Wrath: los golpes conservan una copia del sello activo (hasta 3), y cambiar de sello vuelve a compensar.",
    ["5f3698b"] = "El arma es lo más importante: lo ideal es con poder con hechizos y mucho daño. Con Seal of Command las armas lentas y pesadas son las mejores (hacen más daño Holy Strike y el sello). En lo demás primero Fuerza o poder de ataque, luego Aguante, luego poder con hechizos.",
    ["4c063de"] = "Holy empieza como Retribution: los primeros 12 puntos (hasta el nivel 21) van a Retribution, para tener más eficiencia de maná y Pursuit of Justice. Hasta el 20 tus curas son Holy Light, Lay on Hands y Blessing of Protection: en las misiones en solitario usa Seal of Righteousness, Judgment y Holy Strike como un paladín de daño, sin malgastar maná.",
    ["e1a4083"] = "Con Flash of Light tienes dos curas: Holy Light es lenta y fuerte, para cuando hace falta mucha vida y hay tiempo; Flash of Light es rápida y cuesta menos, para un daño pequeño y constante. Elegir la cura correcta es todo el trabajo: la equivocada quema maná. Desde el 20 también Consecration, Exorcism y Blessing of Kings.",
    ["42143bb"] = "Desde el 22 los puntos van a Holy: Spiritual Focus (los golpes que recibes retrasan menos tus lanzamientos), luego Reverence (parte de la regeneración de maná continúa mientras lanzas) y Healing Light (más curación para Holy Light, Flash of Light y Holy Shock).",
    ["a1c4391"] = "Cómo curar: si el tanque recibe daño constante usa Flash of Light o Holy Light; para un daño repentino Holy Shock; en una emergencia Lay on Hands (gasta todo tu maná). Blessing of Protection sobre un aliado que recibe daño físico, nunca sobre el tanque: si se vuelve inmune los enemigos se giran hacia los demás.",
    ["e98c82f"] = "Illumination: una cura crítica de Flash of Light, Holy Light o Holy Shock puede devolverte maná (la mitad del coste base), así que importan Intelecto y golpe crítico. Desde el 37 Oath of Light sobre el objetivo principal; desde el 38 Infusion of Light: una cura crítica de Holy Shock o Flash of Light hace más rápido tu siguiente Holy Light.",
    ["3bb92dd"] = "A los 40 tienes la doble especialización (mantén Retribution como segunda especialización para las misiones en solitario) y las armaduras de placas. Desde el 42 Holy Shock: una cura instantánea con 10 segundos de reutilización, o daño sagrado a un enemigo. Desde el 45 Divine Favor: tu siguiente cura es siempre crítica (2 minutos de reutilización), para cuando el tanque está en peligro. Desde el 47 Holy Power hace más probables los críticos de Holy Shock y Holy Strike.",
    ["31364c3"] = "Light's Vigil: un efecto de 30 segundos sobre un aliado; un Holy Shock sobre el mismo objetivo lo activa, cura también al grupo y no inicia la reutilización de Holy Shock. Cuesta mucho y solo puede haber uno por grupo: guárdalo para el daño sobre varios jugadores. Sobre un enemigo devuelve el 75% del maná. Los últimos puntos (desde el 56) van a Divine Intellect.",
    ["7fda0df"] = "Para Holy primero va el poder de curación, luego el Intelecto (más maná y más críticos, que devuelven maná con Illumination), luego el maná cada 5 segundos y el Espíritu (con Reverence parte de la regeneración continúa mientras lanzas). El arma es por sus estadísticas, no por su daño: una maza con curación y Espíritu es mejor que un arma con más DPS. Malla hasta el 40, luego placas, pero una pieza de tela con las estadísticas correctas vale más que una de malla sin ellas.",
    ["a531e3f"] = "Seal of Fury es el sello del tanque: cada golpe hace daño sagrado extra y con el escudo obtienes una absorción igual a la mitad de ese daño. Su Judgment te hace provocar durante 3 segundos desde 10 metros. Righteous Fury aumenta toda tu amenaza un 33%. Desde el 22 pasas al árbol Protection, después de Pursuit of Justice.",
    ["8279baa"] = "Blessing of Kings, Retribution Aura y Righteous Fury activo. Mantén siempre Seal of Fury. Juzga mientras corres hacia el monstruo para provocar. Pon Consecration en cuanto estés cuerpo a cuerpo, si el maná lo permite. Luego Holy Strike en cada reutilización y Exorcism sobre no-muertos y demonios. Reúne hasta cuatro enemigos y quémalo todo con Consecration.",
    ["34e2900"] = "Shield Specialization: un bloqueo te devuelve el 4% del maná máximo, como mucho cada 3 segundos: es gran parte de tu maná.",
    ["cc3ac76"] = "Templar's Bulwark: un escudo que absorbe daño igual a toda tu vida durante 8 segundos, pero te da Forbearance durante un minuto. Desde el 37 Swift Judgement: el Judgment del sello se lanza solo con 1 minuto de reutilización, así que tienes una segunda provocación.",
    ["be55413"] = "Holy Shield: durante 10 segundos bloqueas más a menudo y hasta 4 bloqueos hacen daño sagrado. Reckoning (desde el 43) puede dar un ataque extra tras un bloqueo o un golpe crítico recibido.",
    ["e76d8e9"] = "Para Protection el poder con hechizos va primero (Seal of Fury, Holy Shield y Consecration hacen daño sagrado), luego Fuerza y Aguante. Para el arma mejor una más rápida: Seal of Fury golpea en cada golpe. Un arma con poder con hechizos puede valer un poco menos de daño.",
    ["05e5db7"] = "Shadow Word: Pain; misión de clase corta (una túnica)",
    ["c95888a"] = "Mind Blast, Resurrection; la misión de raza enseña la primera habilidad solo de tu raza",
    ["091c0cd"] = "Holy Fire, Flash Heal, Devouring Plague, Fear Ward, Mind Soothe, Shackle Undead; la segunda habilidad racial",
    ["71b2a72"] = "Fortitude sobre ti antes del pull. Abre con Smite, pon Shadow Word: Pain sobre el objetivo y remátalo con la varita, que no cuesta maná y al principio hace gran parte de tu daño (quédate quieto medio segundo antes de usarla). Si el monstruo te alcanza, primero Power Word: Shield. Lo más importante es tener una buena varita: sustitúyela cada vez que encuentres una mejor.",
    ["e023128"] = "Mind Blast es el golpe fuerte con reutilización corta. Los primeros siete puntos de talento son iguales para todas las especializaciones: Wand Specialization (10-11) y Spirit Tap (12-16). Con Spirit Tap, cada muerte de un monstruo que da experiencia duplica tu Espíritu durante 15 segundos y durante ese tiempo la mitad de la regeneración de maná continúa mientras lanzas: menos pausas para beber.",
    ["8df287d"] = "Inner Fire: armadura extra, cada golpe que recibes gasta una carga. Mantenlo, junto con Fortitude, siempre sobre ti y vuelve a lanzarlo cuando termine.",
    ["bebe913"] = "Psychic Scream hace huir a los enemigos cercanos, pero ojo: pueden traer de vuelta a otros monstruos.",
    ["ffa87bf"] = "El maestro hoy te enseña más que en cualquier otro nivel: Holy Fire (apertura lenta pero fuerte, además quema con el tiempo), Flash Heal (rápido pero caro), Devouring Plague (daño con el tiempo que te cura) y otras.",
    ["084f80e"] = "Shadow es la especialización recomendada para subir de nivel en solitario: los puntos van a Shadow Word: Pain, Mind Blast y Mind Flay, así los monstruos mueren antes.",
    ["f33a503"] = "Pon Shield sobre ti si el monstruo te alcanza. Abre con Mind Blast, luego Shadow Word: Pain. Desde el 27 también Devouring Plague y Mind Flay, y tras Shadow Word: Pain añade Vampiric Embrace para que tu daño de sombras te cure. Luego remata con la varita. Si el maná es bajo sáltate Devouring Plague y Mind Flay.",
    ["496ef3d"] = "Shadow Word: Death es daño repentino, pero si el objetivo sobrevive recibes el 30% de tu vida máxima: guárdalo para el golpe final.",
    ["edd0d02"] = "Shadowform: quédate en Shadowform mientras combates (+10% de daño de sombras, los hechizos de sombras cuestan la mitad de maná, -15% de daño físico, pero no puedes lanzar curaciones: sal antes de curar). Abre con Mind Blast, luego Shadow Word: Pain, Vampiric Embrace, Devouring Plague y Mind Flay. Cuando un golpe más mata al monstruo: Shadow Word: Death, o deja el último trozo a la varita. Shield sobre ti si el monstruo te alcanza.",
    ["b912dce"] = "Para Shadow primero el poder con hechizos (también el de sombras sirve: casi todo tu daño es de sombras), luego crítico y Golpe (Hit). La varita es muy importante: al principio hace gran parte del daño.",
    ["8e3f775"] = "Discipline es la especialización de curación que recomendamos para jugar en solitario: desde el 20 Power in Light añade daño a Smite.",
    ["916c9c2"] = "Abre con Holy Fire desde lejos, Smite mientras llega el monstruo, luego Mind Blast, Shadow Word: Pain y la varita. Si el combate va mal: Shield sobre ti, luego cúrate: Flash Heal si lo necesitas rápido, Heal si tienes tiempo.",
    ["a80f7e5"] = "Penance: una ráfaga de golpes sagrados que daña a un enemigo o cura a un aliado, 12 segundos de reutilización, el primer golpe sale al instante.",
    ["037a666"] = "Primero Shield sobre ti. Abre con Holy Fire desde lejos. Smite mientras el monstruo camina, luego Penance sobre el mismo objetivo porque Power in Light lo hace golpear más fuerte. Luego Mind Blast y Shadow Word: Pain. Para rematar Shadow Word: Death si un golpe mata, si no la varita. Cada vez que Weakened Soul desaparece puedes protegerte de nuevo.",
    ["9d0affc"] = "Power Infusion: +20% de daño y curación durante 15 segundos, sobre ti o un amigo: lánzala sobre ti justo antes de abrir, cada vez que esté lista. En el 60 Inner Focus para emergencias: el siguiente hechizo es gratis.",
    ["8e7cd8d"] = "Para Discipline y Holy busca poder de curación y regeneración de maná, luego Intelecto y Espíritu. Elige el arma con estas mismas estadísticas: no importa si es un bastón o una de una mano con mano secundaria.",
    ["c5c1351"] = "Pon Shield y Renew sobre ti antes del pull. Luego abre con Holy Fire, Smite mientras llega el monstruo, Mind Blast y Shadow Word: Pain. Remata con Shadow Word: Death si mata o con la varita.",
    ["575bdd0"] = "Holy Nova daña a cada enemigo cercano y cura al grupo: cuesta mucho maná, así que úsala con varios enemigos encima, o cuando es gratis (Searing Light desde el 43: Holy Fire puede hacer gratis la próxima Holy Nova).",
    ["6953353"] = "Antes del pull pon sobre ti Shield, Renew y Prayer of Mending (cura la próxima vez que el objetivo recibe daño y luego salta a otro del grupo, 10 segundos de reutilización).",
    ["a5c9096"] = "Para Holy busca poder de curación y regeneración de maná, luego Intelecto y Espíritu. Elige el arma con estas mismas estadísticas.",
    ["aa71e89"] = "Backstab (necesita una daga, solo por la espalda), Pick Pocket",
    ["2e3c463"] = "Slice and Dice, Sprint, Sap; misión de clase (Blade of Cunning)",
    ["3a2246d"] = "Ambush (necesita una daga), Poised (pasiva)",
    ["8abd601"] = "Rupture; misión de los venenos: Instant Poison y Crippling Poison",
    ["6c840ea"] = "Shank (nueva en Forever)",
    ["f3d428e"] = "Mutilate (talento de Assassination)",
    ["3e307c7"] = "Death Mark (talento de Subtlety), Slice and Dice rango 2",
    ["f14c847"] = "Shank rango 2",
    ["a554ba3"] = "Camina hasta el monstruo y usa Sinister Strike mientras tengas puntos de combo, luego Eviscerate: más puntos, golpe más fuerte. Stealth por ahora puede quedarse en la barra. Si el combate se pone mal: Evasion y Gouge para detener un lanzamiento o ganar unos segundos.",
    ["44b2b7e"] = "Slice and Dice (un remate: atacas un 20% más rápido, más tiempo con más puntos), Sprint (50% más rápido durante 15 segundos, no rompe Stealth) y Sap para sacar a un humanoide del combate antes de empezar.",
    ["665b56f"] = "Rupture: un sangrado más largo con más puntos. Con la misión de los venenos, Instant Poison y Crippling Poison.",
    ["d06b2e0"] = "Shank: un golpe de la mano secundaria que no puede fallar; el primer rango cuesta 5 de energía, devuelve 15 y se recarga en 10 segundos. Desde el 26 Cheap Shot desde sigilo: aturde durante 4 segundos y da 2 puntos.",
    ["6974c7f"] = "Combat es el duelista: combate cuerpo a cuerpo con el arma que prefieras, funciona con cualquier arma y no necesita sigilo para empezar. Es la recomendada para subir de nivel en solitario.",
    ["cea5a19"] = "Riposte: tras una parada tuya se ilumina y golpea por una vez y media el daño del arma, desarma al monstruo durante 6 segundos y cuesta solo 10 de energía con 6 segundos de reutilización.",
    ["5288c4d"] = "Instant Poison en ambas armas. Cheap Shot desde sigilo para un combate duro, si no Sinister Strike enseguida. Riposte justo tras una parada. Sinister Strike para los puntos con Shank en reutilización: los primeros cinco puntos en Slice and Dice, los cinco siguientes en Eviscerate.",
    ["869d1bf"] = "Con dos monstruos encima: Blade Flurry (cada 2 minutos, durante 15 segundos atacas un 20% más rápido y cada golpe alcanza también a un segundo cercano).",
    ["9fb5eb8"] = "Adrenaline Rush (cada 5 minutos: la energía vuelve el doble de rápido durante 15 segundos) para un monstruo peligroso.",
    ["f8cc28b"] = "Cold Blood justo antes de un Eviscerate grande.",
    ["625324b"] = "Armadura de cuero con Agilidad: es la que quieres. Golpe (Hit), crítico, poder de ataque y Aguante son útiles. Combat puede usar cualquier tipo de arma, porque Hack and Slash da una bonificación por cada una: espadas y hachas, dagas y armas de puño, mazas.",
    ["d01cb25"] = "Assassination es el envenenador: venenos y remates se vuelven cada vez más fuertes, y en el 40 llega Mutilate.",
    ["9eb3d72"] = "Instant Poison en ambas armas. Desde sigilo abre con Garrote o Cheap Shot. Sinister Strike para los puntos y Shank en reutilización. Slice and Dice, luego Eviscerate; guarda Cold Blood para un Eviscerate grande.",
    ["33aceb3"] = "Venom: durante 6 segundos tras cada Shank tus venenos golpean un 30% más fuerte y un 20% más a menudo. Shank en reutilización.",
    ["88ede56"] = "Mutilate construye los puntos: golpea con las dos armas, un 20% más fuerte sobre un objetivo envenenado, y da 2 puntos. Hacen falta dos dagas. Slice and Dice, Shank en reutilización para Venom, luego Eviscerate; Cold Blood sobre un Eviscerate grande.",
    ["20500ff"] = "Armadura de cuero con Agilidad. Assassination necesita dagas para Backstab, Ambush y Mutilate. Golpe (Hit), crítico, poder de ataque y Aguante son útiles.",
    ["5259278"] = "Subtlety es el emboscador: abre cada combate desde las sombras con una daga en la mano.",
    ["64f4a07"] = "Daga en la mano principal, Instant Poison en ambas armas. Acércate por la espalda del monstruo, Premeditation, luego Ambush, luego Ghostly Strike, luego Garrote. Sinister Strike construye el resto; Shank en reutilización para la energía; Eviscerate remata.",
    ["37c1365"] = "Hemorrhage construye los puntos en lugar de Sinister Strike.",
    ["c0f22d5"] = "Hemorrhage y Shank construyen los puntos, y con Boot Knife cada Shank vale dos. Death Mark almacena daño durante 6 segundos: gasta en él un juego completo de puntos cuando el monstruo viva lo bastante, luego Eviscerate para rematar. Si el combate va mal, Preparation reinicia Premeditation, Ghostly Strike y tus otras reutilizaciones.",
    ["a993dd2"] = "Armadura de cuero con Agilidad. Subtlety lleva una daga en la mano principal (Ambush y Backstab la requieren). Golpe (Hit), crítico, poder de ataque y Aguante son útiles.",
    ["abbb551"] = "Earth Shock; misión del tótem de tierra: Stoneskin Totem",
    ["8e8845b"] = "Misión del tótem de fuego: Searing Totem",
    ["2be8a5e"] = "Ghost Wolf, Frost Shock, Lesser Healing Wave, Frostbrand Weapon, Healing Stream Totem (misión del tótem de agua), Call of the Elements, Totemic Recall",
    ["0a8c77d"] = "Windfury Weapon, Reincarnation (necesita un Ankh), Astral Recall, Grounding Totem",
    ["47fd721"] = "Chain Lightning, Windfury Totem; misión del tótem de aire (las armas de la tormenta)",
    ["b821239"] = "Chain Heal, armadura de malla",
    ["d6b5209"] = "Rockbiter Weapon se queda en el arma y desde el 8 Lightning Shield se pone antes del pull. Abre con Lightning Bolt y en cuanto llegue Earth Shock, que es instantáneo; contra un lanzador guarda el choque para interrumpir su lanzamiento. Cuando el monstruo está encima lo rematan los golpes cuerpo a cuerpo. Si llega otro monstruo pon Earthbind Totem: lo ralentiza y te deja hacer kiting. Al final del combate Healing Wave si estás herido.",
    ["fa734a3"] = "Cada especialización tiene un papel claro: Enhancement combate cuerpo a cuerpo con un arma grande, tótems y choques; Elemental se queda a distancia con Lightning Bolt, Chain Lightning y Fire Nova; Restoration cura y está en grupo o en mazmorras, no en solitario haciendo misiones. Si te quedas sin maná Enhancement sigue golpeando (la muerte tarda más), Elemental sufre más.",
    ["b74be3c"] = "Flame Shock golpea al instante con fuego y luego quema durante 12 segundos. Flametongue Weapon añade daño de fuego a cada golpe; Searing Totem es una torreta pequeña que dispara a un enemigo cercano.",
    ["35c7293"] = "Enhancement es la especialización que recomendamos para las misiones. Tiene sus puntos débiles: un arma mala baja mucho el daño, los costes de maná al principio pesan y contra muchos enemigos a la vez le cuesta.",
    ["028a6b7"] = "Stormstrike golpea al instante con todo el daño del arma cada 8 segundos, y el objetivo recibe un 20% más de tu próximo Lightning Bolt, Chain Lightning o Earth Shock.",
    ["a94041d"] = "Stormstrike cada vez que está listo, y justo después Earth Shock (el golpe de Stormstrike hace el choque más fuerte). Rockbiter Weapon siempre en el arma y Lightning Shield sobre ti. Antes del pull Strength of Earth y Mana Spring y, si el maná lo permite, Searing Totem o Magma Totem. Abre con Lightning Bolt rango 1 (el más barato), luego los golpes normales hacen el resto. Fire Nova solo si los monstruos están en el radio de tu tótem de fuego y aún tienes maná. Tras la muerte Healing Wave, y bebe si el maná es bajo.",
    ["18a8896"] = "Windfury Weapon en el arma en lugar de Rockbiter: cada golpe tiene un 20% de dar dos ataques más, es la pieza grande de Enhancement. Si una esquiva o una parada reinicia Stormstrike, púlsalo otra vez enseguida. Windfury Totem, con Grounding Totem en su lugar contra lanzadores.",
    ["f3777c4"] = "Maelstrom Weapon: tus golpes acumulan hasta 5 cargas y cada carga hace el próximo Lightning Bolt más rápido y más barato: con 5 cargas lanza Lightning Bolt al rango más alto. Desde el 46 Water Shield ocupa el lugar de Lightning Shield (solo puedes tener uno).",
    ["022a55d"] = "Para Enhancement el arma cuenta ante todo: lo ideal es una de dos manos lenta, entre 3,3 y 3,8 de velocidad. Luego Fuerza y poder de ataque, con el Intelecto justo detrás, porque alimenta Mental Dexterity y el maná.",
    ["4540d89"] = "Earthbound: cuando pones Earthbind Totem los enemigos cercanos quedan inmovilizados 5 segundos.",
    ["bcd1d77"] = "Antes del pull Mana Spring Totem y un tótem de fuego (Searing contra un monstruo, Magma contra varios), Lightning Shield sobre ti. Abre al límite del alcance con Lightning Bolt, pon Flame Shock sobre el objetivo y sigue con Lightning Bolt. Con tres o más monstruos Fire Nova cada vez que esté listo. Earth Shock interrumpe a un lanzador y lo trae hacia ti. Earthbind Totem cuando los monstruos se acercan. Cúrate y bebe al final.",
    ["13a3832"] = "Contra un solo monstruo: Searing Totem, abre desde lejos con Lightning Bolt, Flame Shock, sigue con Lightning Bolt. Contra tres o más: Magma Totem, abre con Chain Lightning, Flame Shock sobre uno de ellos, luego Chain Lightning y Fire Nova en cada reutilización con Lightning Bolt en medio.",
    ["2c3ba7a"] = "Lightning Mastery (15 segundos, luego 3 minutos): durante 15 segundos Lightning Bolt se lanza más rápido y Chain Lightning ignora su reutilización. Úsalo en un élite o un pull grande, si no en cada reutilización.",
    ["b56c9ed"] = "Water Shield ocupa el lugar de Lightning Shield sobre ti.",
    ["4688073"] = "Para Elemental busca poder con hechizos, con el Intelecto sobre todo para el maná. Desde el nivel 40 puedes ponerte malla.",
    ["b4ca62b"] = "Antes del pull Water Shield, Mana Spring Totem y los tótems que el grupo pueda usar. Mientras alguien recibe daño, Healing Wave es el caballo de batalla. Lesser Healing Wave se lanza en 1,5 segundos y cura menos por el maná: guárdala para los momentos en que cuenta el tiempo. Mana Tide Totem (12 segundos, 5 minutos de reutilización) cuando todo el grupo se queda sin maná. Cuando nadie está en peligro añade daño: Lightning Bolt sobre un objetivo, Fire Nova sobre un grupo. Bebe al final.",
    ["42937c0"] = "Nature's Swiftness (cada 3 minutos): tu próximo hechizo de naturaleza es instantáneo, así que una Healing Wave instantánea para un amigo que está a punto de morir. Windfury Totem si hay jugadores cuerpo a cuerpo.",
    ["9b2d19c"] = "Riptide: curación con el tiempo con 12 segundos de reutilización, y una Chain Heal lanzada justo sobre el objetivo de Riptide es un 25% más fuerte. Chain Heal cura al objetivo y a otros dos aliados, así que cubre el daño repartido por el grupo.",
    ["a86408d"] = "Para Restoration busca poder de curación, con el Intelecto sobre todo para el maná. Desde el nivel 40 puedes ponerte malla.",
    ["c86a1be"] = "Voidwalker (misión de clase), Drain Soul, Healthstone",
    ["40cb6b4"] = "Succubus e Incubus (misiones de clase), Demon Armor, Curse of the Elements, Rain of Fire, Ritual of Summoning",
    ["df7bfa2"] = "Felhunter (misión de clase), Hellfire",
    ["19e5308"] = "Howl of Terror, Felsteed (misión)",
    ["1c5b068"] = "El demonio entra primero, luego Bane of Agony y Corruption; solo los monstruos más duros reciben Immolate, porque el demonio los aguanta. El orden importa porque el daño atrae la atención: los primeros ticks de Agony son pequeños, así que el demonio retiene al monstruo hasta que un Immolate nuevo golpea lo bastante fuerte para que se vuelva hacia ti. Mantén Demon Skin, sáltate los DOTs en un monstruo casi muerto y no renueves Agony mientras siga haciendo daño. Hasta que tengas una varita Shadow Bolt termina el trabajo; luego consigue una varita: cada disparo es maná ahorrado para el siguiente pull.",
    ["ea42414"] = "Drain Soul es tu fuente principal de Soul Shards: un monstruo no trivial que muere con su drenaje siempre da una. Cuando tengas pocas remata las muertes con él. Healthstone, Soul Stone y las invocaciones de Voidwalker, Succubus y Felhunter requieren fragmentos.",
    ["72f97d5"] = "Drain Life cambia cómo lees la pantalla: si la barra azul está baja y tu vida va bien, Life Tap; si tu vida ha bajado de verdad, Drain Life sobre el monstruo. Así casi todo el tiempo muerto desaparece.",
    ["51205f3"] = "Demon Armor en lugar de Demon Skin. Con Ritual of Summoning tú y dos compañeros traéis a un miembro del grupo que aún está lejos. Un Fear te da unos segundos gratis para una venda.",
    ["9d83c05"] = "Si juegas en solitario, Affliction es la elección: la precisión y una Corruption instantánea llegan pronto. Curse of the Elements va junto a Agony. Desde el 25 Nightfall puede saltar por el daño de Corruption, Drain Life o Drain Soul, y el Shadow Bolt tras el proc no tiene tiempo de lanzamiento. Puedes coger el talento de los drenajes un poco antes del 30 y apoyarte en Drain Life en cada combate.",
    ["04f03c2"] = "Siphon Life: un tick cada 3 segundos durante 30 segundos, así que un monstruo que muere en 10 solo recibe un tercio. Guárdalo para los combates largos.",
    ["703c37f"] = "Demonic Sacrifice: sacrificas al Felhunter y durante dos horas recuperas el 3% de tu vida total cada 4 segundos; invocar un demonio lo anula, así que de aquí en adelante haces misiones casi sin mascota.",
    ["2dbcea6"] = "Wrack: canalizas durante 6 segundos, hace daño de sombras, y tus otros DOTs de sombras sobre ese objetivo golpean un 10% más fuerte mientras dura.",
    ["edb7e47"] = "Elige armas con poder con hechizos, porque casi nunca las usarás para golpear. Al principio una mejora de varita supera a casi todas las demás; después, el poder con hechizos va primero. El Aguante es vida extra para convertir en maná con Life Tap, el Intelecto una reserva de maná más grande, el Espíritu rinde más con cada Life Tap.",
    ["1c3a6a3"] = "Si prefieres ver trabajar al demonio, Demonology: con Demonic Brand desde el 25. Desde el 25 Searing Pain pone una marca en el objetivo durante 10 segundos, y como mucho los primeros seis golpes de tu demonio hacen daño extra: renuévala con un Searing Pain rápido sobre lo que combate el demonio y rellena los huecos con DOTs y la varita.",
    ["00d4a86"] = "Soul Link: el 30% de cada golpe directo a ti va al demonio, y los dos hacéis un 3% más de daño. Se pierde cuando cambias de demonio: vuelve a lanzarlo cada vez.",
    ["a3cee7a"] = "Demonic Pact: el sacrificio sobrevive al cambio de demonio, a menos que invoques justo el que sacrificaste. En una mazmorra sacrifica al Imp (15% más de daño de sombras); en misiones en solitario al Felhunter por sus curaciones, y combate junto a un Voidwalker, Succubus o Incubus. Desde el 27 también puedes subir como Affliction y cambiar de especialización: tienes los puntos para los tres rangos de Demonic Brand.",
    ["545f2c9"] = "Destruction se puede jugar desde el 10, pero se vuelve mucho más fuerte en el 39 y el 40, y pasa más tiempo quieta lanzando que las otras dos: también puedes elegirla más tarde.",
    ["0b5d29c"] = "Shadowburn: un golpe instantáneo que cuesta un Shard y te lo devuelve si un objetivo no trivial muere en 8 segundos.",
    ["124afde"] = "La apertura cambia: Shadow Bolt desde la distancia máxima e Immolate mientras el rayo sigue en vuelo. Así el monstruo va hacia ti y no hacia el demonio, así que elige combates que puedas cerrar rápido. Shadowburn remata a los monstruos; Conflagrate es mejor guardarlo para el final de tu Immolate.",
    ["07ea333"] = "Con Shadow and Flame, Conflagrate sube tu daño de sombras un 20% y Shadowburn tu daño de fuego un 20%; Conflagrate ya no consume Immolate y Shadowburn siempre devuelve el Shard. Desde el 39 no hay motivo para contenerlos.",
    ["609f38c"] = "Incinerate hace un 25% más a todo lo que ya está ardiendo por tu Immolate.",
    ["a1d5005"] = "Defensive Stance, Taunt, Sunder Armor (misión de clase), Bloodrage",
    ["b87bfb2"] = "Revenge, Demoralizing Shout, Tactical Mastery (se aprende del maestro)",
    ["a61955b"] = "Victory Rush, Cleave, Slam, Retaliation; puedes usar dos armas",
    ["323f468"] = "Berserker Stance, Berserker Rage, Intercept (misión de clase)",
    ["b289adb"] = "Armadura de placas y montura",
    ["2debde0"] = "Battle Shout antes del pull, Charge, Rend sobre lo que vive mucho, luego deja que los golpes normales acumulen ira. Heroic Strike solo con ira que no necesites: sustituye a un golpe normal y ese golpe no da ira. Con varios monstruos Thunder Clap; no gastes ira en un monstruo que está a punto de morir.",
    ["f98c5d6"] = "Bloodrage entre pulls: cuesta un poco de vida y da 10 de ira al instante y 10 en 10 segundos. Nunca empieces un combate sin ira.",
    ["970305a"] = "Victory Rush cada vez que se ilumina: tras una muerte que da experiencia tienes 20 segundos, hace daño y te cura un 10%, 30 segundos de reutilización y no cuesta ira.",
    ["a60b4a3"] = "Desde el 14 Revenge es tu ataque principal: úsalo cada vez que se ilumina (tras un bloqueo, una esquiva o una parada). Pasa a escudo y arma de una mano. Thunder Clap y Demoralizing Shout sobre los grupos.",
    ["41fd2f0"] = "Charge, luego quédate en Defensive Stance. Mantén Shield Block contra quien te golpee cuerpo a cuerpo, y sáltate Shield Block contra los lanzadores. Revenge cada vez que se ilumina; Rend y algún Sunder Armor sobre los monstruos que viven mucho; Thunder Clap y Demoralizing Shout sobre los grupos.",
    ["b604238"] = "Con Vanguard puedes hacer Charge desde Defensive Stance: puedes abrir un pull sin cambiar de postura, si estás fuera de combate.",
    ["c9e7c22"] = "Shield Wall: 60% menos de daño durante 12 segundos, para los pulls que van mal.",
    ["3f0c2f4"] = "Shield Slam es el golpe más fuerte (el daño crece con tu valor de bloqueo): úsalo primero y Revenge justo después. Si tienes poca ira Revenge primero, cuesta menos.",
    ["846367b"] = "Protection quiere sobre todo Fuerza (cada punto da 2 de poder de ataque y valor de bloqueo). Para el arma coge el mejor DPS: Revenge y Shield Slam no dependen del arma. La Agilidad cuenta menos: da crítico, esquiva y armadura pero ningún poder de ataque.",
    ["fabdcb6"] = "Rend primero, luego Overpower cada vez que se ilumina (tras una esquiva del objetivo).",
    ["f29cf52"] = "Rend, luego Overpower cuando se ilumina. Desde el 20 Slam justo después de un golpe.",
    ["60998aa"] = "Sweeping Strikes: tus próximos cinco golpes también alcanzan a un segundo enemigo cercano, es un gran salto. Empieza sobre un monstruo mientras te sobre ira, luego trae a un segundo monstruo y usa Sweeping Strikes y Cleave sobre los dos.",
    ["efc030d"] = "Con Bloodthrill, si Rend está sobre el objetivo los golpes de la mano principal tienen un 20% de activar Overpower: Rend se queda en la rotación hasta el 60.",
    ["98a8fec"] = "Mortal Strike es tu nuevo ataque principal.",
    ["7caf705"] = "El arma cuenta más que nada: busca el DPS más alto, y para Arms una de dos manos lenta (cada golpe y Mortal Strike y Slam hacen más daño). En lo demás primero Golpe (Hit, porque un golpe fallado no da ni daño ni ira), luego Fuerza y Crítico. La Agilidad da crítico y esquiva pero ningún poder de ataque.",
    ["ce62f29"] = "Rend sobre los monstruos que viven mucho, Overpower cuando el objetivo esquiva. Si un segundo monstruo está junto al objetivo, gasta la ira extra en Cleave. Elige una mano secundaria rápida: más golpes, más ira.",
    ["1879df1"] = "Death Wish: durante 30 segundos haces un 20% más de daño físico y no pueden asustarte, pero recibes un 5% más de daño. Reckless Swings (31): cuesta un poco de vida y los próximos cuatro golpes dan 5 de ira más cada uno.",
    ["0d27ce4"] = "Con Whirlwind (nivel 36) es tu botón principal, incluso contra un solo monstruo: la reutilización baja a 8 segundos y golpea al más cercano con un 30% más de daño.",
    ["308a3c5"] = "Bloodthirst cada vez que Whirlwind está en reutilización. Desde el 50 tienes Recklessness.",
    ["2d76abd"] = "El arma cuenta más que nada: busca el DPS más alto. Para la mano secundaria una rápida (más golpes, más ira). En lo demás primero Golpe (Hit), luego Fuerza y Crítico. La Agilidad da crítico y esquiva pero ningún poder de ataque.",
}
